CREATE TABLE metadata_config_versions (tenant_id BIGINT UNSIGNED NOT NULL,version BIGINT UNSIGNED NOT NULL,state VARCHAR(12) NOT NULL,configuration JSON NOT NULL,created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),published_at DATETIME(6) NULL,PRIMARY KEY(tenant_id,version),KEY metadata_config_history(tenant_id,created_at,version),CONSTRAINT metadata_config_state CHECK(state IN('DRAFT','PUBLISHED','RETIRED')),CONSTRAINT fk_metadata_config_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,CONSTRAINT fk_metadata_config_user FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
